declare(strict_types=1);require_once __DIR__.'/_helper.php';izin_require_access($pdo);$id=max(0,(int)($_GET['id']??0));$row=izin_get($id,$pdo);if(!$row){http_response_code(404);exit('Data izin tidak ditemukan.');}
if(user_role()==='guru'){if(izin_is_wali($pdo)){ $sc=izin_student_scope_sql($pdo,'s');$chk=$pdo->prepare("SELECT 1 FROM siswa s WHERE s.id=? AND {$sc['sql']} LIMIT 1");$chk->execute(array_merge([(int)$row['siswa_id']],$sc['params']));if(!$chk->fetchColumn())deny_access();}elseif(!izin_is_piket($pdo))deny_access();}
$errors=[];$success='';if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$aksi=(string)($_POST['aksi']??'');$row=izin_get($id,$pdo);if(!$row)$errors[]='Data izin tidak ditemukan.';elseif(in_array($aksi,['setujui','tolak'],true)){if(!izin_is_wali($pdo))$errors[]='Hanya Wali Kelas yang berwenang menyetujui atau menolak.';elseif($row['status']!=='DIAJUKAN')$errors[]='Izin ini sudah tidak berstatus Diajukan.';else{$ok=true;if(user_role()==='guru'){$sc=izin_student_scope_sql($pdo,'s');$chk=$pdo->prepare("SELECT 1 FROM siswa s WHERE s.id=? AND {$sc['sql']} LIMIT 1");$chk->execute(array_merge([(int)$row['siswa_id']],$sc['params']));$ok=(bool)$chk->fetchColumn();if(!$ok)$errors[]='Izin ini bukan siswa dari kelas yang menjadi tanggung jawab Anda.';}if($ok){$new=$aksi==='setujui'?'DISETUJUI':'DITOLAK';$st=$pdo->prepare("UPDATE izin_siswa SET status=?,disetujui_oleh=?,disetujui_at=NOW(),updated_at=NOW() WHERE id=? AND status='DIAJUKAN'");$st->execute([$new,user_id(),$id]);izin_audit($pdo,'IZIN_'.$new,$id,'Izin siswa '.$new.' untuk '.$row['siswa_nama']);$success='Izin berhasil '.strtolower($new).'.';$row=izin_get($id,$pdo);}}}elseif($aksi==='keluar'){if(!izin_is_piket($pdo))$errors[]='Hanya Guru Piket yang berwenang menandai siswa sudah keluar.';elseif($row['status']!=='DISETUJUI')$errors[]='Hanya izin yang disetujui yang dapat ditandai sudah keluar.';else{$st=$pdo->prepare("UPDATE izin_siswa SET status='SELESAI',jam_keluar=NOW(),updated_at=NOW() WHERE id=? AND status='DISETUJUI'");$st->execute([$id]);izin_audit($pdo,'IZIN_KELUAR',$id,'Siswa ditandai sudah keluar/pulang: '.$row['siswa_nama']);$success='Siswa berhasil ditandai sudah keluar.';$row=izin_get($id,$pdo);}}}
$menu=trim((string)($_GET['menu']??''));$menuQuery=$menu!==''?'?menu='.rawurlencode($menu):'';$page_title='Detail Izin Siswa';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?><main class="main"><header class="topbar"><div class="topbar-title">Detail Izin Siswa</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content izin-detail-module"><div class="page-header"><div><h1>Detail Izin Siswa</h1><p><?=e($row['siswa_nama'])?> · <?=e($row['kelas_nama'])?></p></div><a class="btn btn-secondary" href="<?=BASE_URL?>izin/index.php<?=e($menuQuery)?>">← Kembali ke Izin</a></div><?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="form-card"><div class="detail-grid"><div><small>Nama</small><strong><?=e($row['siswa_nama'])?></strong></div><div><small>NIS</small><strong><?=e($row['nis'])?></strong></div><div><small>Kelas</small><strong><?=e($row['kelas_nama'])?></strong></div><div><small>Tapel</small><strong><?=e($row['tapel_nama'])?></strong></div><div><small>Jenis</small><strong><?=e($row['jenis']==='PULANG_LEBIH_AWAL'?'Pulang Lebih Awal':'Keluar Sementara')?></strong></div><div><small>Tanggal</small><strong><?=e($row['tanggal'])?></strong></div><div><small>Jam Pengajuan</small><strong><?=e(substr((string)$row['jam_pengajuan'],0,19))?></strong></div><div><small>Status</small><strong><span class="badge badge-<?=e(izin_status_class($row['status']))?>"><?=e(izin_status_label($row['status']))?></span></strong></div><div style="grid-column:1/-1"><small>Alasan</small><strong><?=e($row['alasan'])?></strong></div><div style="grid-column:1/-1"><small>Keterangan</small><strong><?=e($row['keterangan']?:'-')?></strong></div><?php if($row['disetujui_oleh']):?><div><small>Keputusan oleh</small><strong><?=e($row['penyetuju_nama']?:'-')?></strong></div><div><small>Waktu keputusan</small><strong><?=e($row['disetujui_at']?:'-')?></strong></div><?php endif;?><?php if($row['jam_keluar']):?><div><small>Jam Keluar</small><strong><?=e($row['jam_keluar'])?></strong></div><?php endif;?></div><div class="form-actions" style="margin-top:24px"><?php if($row['status']==='DIAJUKAN'&&izin_is_wali($pdo)):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="aksi" value="setujui"><button class="btn btn-success" onclick="return confirm('Setujui izin siswa ini?')">✓ Setujui</button></form><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="aksi" value="tolak"><button class="btn btn-danger" onclick="return confirm('Tolak izin siswa ini?')">✕ Tolak</button></form><?php endif;?><?php if($row['status']==='DISETUJUI'&&izin_is_piket($pdo)):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="aksi" value="keluar"><button class="btn btn-primary" onclick="return confirm('Tandai siswa sudah keluar/pulang?')">↗ Tandai Sudah Keluar</button></form><?php endif;?></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
